// GetManyByIDs retrieves multiple RecipeRef records by their IDs in a single query
func (r *RecipeRefRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.RecipeRef, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.RecipeRef{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "root_id", "parent_ref_id", "base_commit_id", "head_commit_id", "name", "sealed_at", "created_at", "created_by", "updated_at", "updated_by", "deleted_at", "deleted_by", "_version" FROM recipe_ref WHERE id IN (%s)`, strings.Join(placeholders, ", "))
	query += " AND deleted_at IS NULL"

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.RecipeRef, len(uniqueIDs))
	for rows.Next() {
		entity := &types.RecipeRef{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempSealedAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)
		var tempRelRoot *types.IdentityUUID
		var tempRelParentRef *types.IdentityUUID
		var tempRelBaseCommit *types.IdentityUUID
		var tempRelHeadCommit *types.IdentityUUID

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&tempRelRoot,

			&tempRelParentRef,

			&tempRelBaseCommit,

			&tempRelHeadCommit,

			&entity.Name,

			&tempSealedAt,

			&entity.CreatedAt,

			&entity.CreatedBy,

			&entity.UpdatedAt,

			&entity.UpdatedBy,

			&entity.DeletedAt,

			&entity.DeletedBy,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempSealedAt != nil {
			entity.SealedAt = tempSealedAt
		}

		// Set relationship IDs from scanned FK values
		if tempRelRoot != nil {
			entity.Root.Id = recipeRefUUIDPtr(*tempRelRoot)
		}
		if tempRelParentRef != nil {
			// Initialize pointer for optional relationship before setting ID
			entity.ParentRef = &types.RecipeRef{Id: recipeRefUUIDPtr(*tempRelParentRef)}
		}
		if tempRelBaseCommit != nil {
			// Initialize pointer for optional relationship before setting ID
			entity.BaseCommit = &types.RecipeCommit{Id: recipeRefUUIDPtr(*tempRelBaseCommit)}
		}
		if tempRelHeadCommit != nil {
			// Initialize pointer for optional relationship before setting ID
			entity.HeadCommit = &types.RecipeCommit{Id: recipeRefUUIDPtr(*tempRelHeadCommit)}
		}

		entityID, ok := recipeRefUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

